import React, { useState } from 'react';
import { apiLogin, apiRegister, setToken, setCurrentUser } from '../services/api';
import './LoginPage.css';

interface LoginPageProps {
  onLogin: () => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [captchaChecked, setCaptchaChecked] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username || !password) { setError('Please fill in all fields.'); return; }
    if (isRegister && !email) { setError('Email is required to register.'); return; }
    if (!captchaChecked) { setError('Please verify you are not a robot.'); return; }

    setError('');
    setLoading(true);
    try {
      const data = isRegister
        ? await apiRegister({ username, email, password })
        : await apiLogin({ username, password });

      setToken(data.token);
      setCurrentUser(data.user);
      onLogin();
    } catch (err: any) {
      setError(err.message || 'Something went wrong');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-root">
      {/* Left hero panel */}
      <div className="login-hero">
        <div className="login-hero__brand"></div>
        <div className="login-hero__content">
          <h1 className="login-hero__heading">
            <span className="hero-word hero-word--1">Redefining</span>
            <span className="hero-word hero-word--2">Influencer</span>
            <span className="hero-word hero-word--3">Marketing <span className="hero-word--light">with</span></span>
            <span className="hero-word hero-word--4">AI</span>
          </h1>
          <p className="login-hero__sub">Connect with the right creators. Zero searching required.</p>
        </div>
        <div className="login-hero__decor">
          <div className="hero-circle hero-circle--1" />
          <div className="hero-circle hero-circle--2" />
          <div className="hero-circle hero-circle--3" />
        </div>
      </div>

      {/* Right form panel */}
      <div className="login-panel">
        <div className="login-form-container">
          <div className="login-form-brand">
            <span className="brand-up">Up</span>
            <span className="brand-clout">Clout</span>
          </div>
          <h2 className="login-form-title">{isRegister ? 'Create account' : 'Welcome back'}</h2>
          <p className="login-form-subtitle">{isRegister ? 'Sign up to get started' : 'Sign in to your account'}</p>

          <form className="login-form" onSubmit={handleLogin}>
            <div className="form-group">
              <input
                className="form-input"
                type="text"
                placeholder="Username"
                value={username}
                onChange={e => setUsername(e.target.value)}
                autoComplete="username"
              />
            </div>

            {isRegister && (
              <div className="form-group">
                <input
                  className="form-input"
                  type="email"
                  placeholder="Email"
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                  autoComplete="email"
                />
              </div>
            )}

            <div className="form-group">
              <div className="input-with-icon">
                <input
                  className="form-input"
                  type={showPassword ? 'text' : 'password'}
                  placeholder="Password"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  autoComplete="current-password"
                />
                <button
                  type="button"
                  className="eye-toggle"
                  onClick={() => setShowPassword(v => !v)}
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? (
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/>
                      <path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/>
                      <line x1="1" y1="1" x2="23" y2="23"/>
                    </svg>
                  ) : (
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
                      <circle cx="12" cy="12" r="3"/>
                    </svg>
                  )}
                </button>
              </div>
            </div>

            <div className="captcha-row">
              <div
                className={`captcha-box ${captchaChecked ? 'captcha-box--checked' : ''}`}
                onClick={() => setCaptchaChecked(v => !v)}
                role="checkbox"
                aria-checked={captchaChecked}
                tabIndex={0}
                onKeyDown={e => e.key === ' ' && setCaptchaChecked(v => !v)}
              >
                <div className="captcha-checkbox">
                  {captchaChecked && (
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#2563eb" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                      <polyline points="20 6 9 17 4 12"/>
                    </svg>
                  )}
                </div>
                <span className="captcha-label">I'm not a robot</span>
                <div className="captcha-logo">
                  <svg width="24" height="24" viewBox="0 0 64 64" fill="none">
                    <circle cx="32" cy="32" r="30" fill="#4A90D9"/>
                    <path d="M20 32 Q32 16 44 32 Q32 48 20 32Z" fill="white" opacity="0.8"/>
                    <circle cx="32" cy="32" r="6" fill="white"/>
                  </svg>
                  <div className="captcha-logo-text">
                    <span>reCAPTCHA</span>
                    <span>Privacy · Terms</span>
                  </div>
                </div>
              </div>
              {!isRegister && (
                <button type="button" className="forgot-btn">Forgot password?</button>
              )}
            </div>

            {error && <div className="form-error">{error}</div>}

            <button
              type="submit"
              className={`login-btn ${loading ? 'login-btn--loading' : ''}`}
              disabled={loading}
            >
              {loading ? (
                <span className="spinner" />
              ) : isRegister ? 'REGISTER' : 'LOGIN'}
            </button>
          </form>

          <p className="register-link">
            {isRegister ? 'Already have an account? ' : "Don't have an account? "}
            <button
              type="button"
              className="register-btn"
              onClick={() => { setIsRegister(v => !v); setError(''); }}
            >
              {isRegister ? 'Login' : 'Register here'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
